import { Box, Typography } from '@mui/material';
import { PieChart } from '@mui/x-charts/PieChart';
import { PieChart as PieIcon } from 'lucide-react';

const COLORS = ['#f97316', '#fb923c', '#fdba74', '#fbbf24', '#f59e0b', '#d97706'];

export default function CategoryPieChart({ data }) {
  const totalRev = data.reduce((s, c) => s + c.revenue, 0);

  return (
    <Box sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid', borderColor: 'divider', p: { xs: 2, md: 2.5 }, height: '100%' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
        <PieIcon size={18} color="#f97316" />
        <Typography variant="h6">Répartition par Catégorie</Typography>
      </Box>
      <PieChart
        series={[{
          data: (data || []).map((c, i) => ({ id: i, value: c.percentage, label: c.name, color: COLORS[i % COLORS.length] })),
          innerRadius: 55, outerRadius: 90, paddingAngle: 3, cx: '50%', cy: '45%',
        }]}
        height={250}
        slotProps={{ legend: { hidden: true } }}
      />
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(3, 1fr)', md: 'repeat(6, 1fr)' }, gap: 0.5, mt: 1 }}>
        {data.map((c, i) => (
          <Box key={c.name} sx={{ textAlign: 'center', p: 0.5 }}>
            <Box sx={{ width: 8, height: 8, borderRadius: '50%', bgcolor: COLORS[i % COLORS.length], mx: 'auto', mb: 0.3 }} />
            <Typography sx={{ fontWeight: 700, fontSize: '0.78rem', color: COLORS[i % COLORS.length] }}>{c.percentage}%</Typography>
            <Typography variant="body2" sx={{ fontSize: '0.6rem', lineHeight: 1.2 }}>{c.name}</Typography>
          </Box>
        ))}
      </Box>
    </Box>
  );
}
