import { Box, Typography } from '@mui/material';
import { CheckCircle, XCircle } from 'lucide-react';

export default function ConfusionMatrix({ data }) {
  const items = [
    { label: 'Vrais Positifs (TP)', key: 'true_positives', ok: true, desc: 'Produits correctement recommandés' },
    { label: 'Faux Positifs (FP)', key: 'false_positives', ok: false, desc: 'Produits recommandés à tort' },
    { label: 'Faux Négatifs (FN)', key: 'false_negatives', ok: false, desc: 'Produits non recommandés mais auraient dû l\'être' },
    { label: 'Vrais Négatifs (TN)', key: 'true_negatives', ok: true, desc: 'Produits correctement non recommandés' },
  ];

  const total = (data.true_positives + data.false_positives + data.true_negatives + data.false_negatives) || 1;
  const acc = ((data.true_positives + data.true_negatives) / total * 100).toFixed(1);

  return (
    <Box sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid', borderColor: 'divider', p: { xs: 2, md: 2.5 }, height: '100%' }}>
      <Typography variant="h6" sx={{ mb: 2 }}>Matrice de Confusion</Typography>
      <Typography variant="body2" sx={{ mb: 1.5, fontSize: '0.72rem' }}>
        Répartition des prédictions du modèle sur {total.toLocaleString('fr-FR')} produits testés
      </Typography>
      <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5 }}>
        {items.map((m) => {
          const val = data[m.key] ?? 0;
          return (
            <Box key={m.key} sx={{
              p: { xs: 1.5, md: 2 }, borderRadius: 2, textAlign: 'center',
              background: m.ok ? 'rgba(16,185,129,0.08)' : 'rgba(239,68,68,0.08)',
              border: '1px solid', borderColor: m.ok ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)',
            }}>
              {m.ok ? <CheckCircle size={18} color="#10b981" style={{ marginBottom: 4 }} /> : <XCircle size={18} color="#ef4444" style={{ marginBottom: 4 }} />}
              <Typography sx={{ fontSize: { xs: '1.15rem', md: '1.4rem' }, fontWeight: 700, fontFamily: 'monospace', color: m.ok ? '#10b981' : '#ef4444' }}>
                {val.toLocaleString('fr-FR')}
              </Typography>
              <Typography sx={{ fontSize: '0.72rem', color: '#9ca3af', mt: 0.3 }}>{m.desc}</Typography>
            </Box>
          );
        })}
      </Box>
      <Box sx={{ mt: 2, p: 1.5, borderRadius: 2, background: 'rgba(249,115,22,0.06)', border: '1px solid rgba(249,115,22,0.15)', textAlign: 'center' }}>
        <Typography variant="body2" sx={{ fontSize: '0.78rem' }}>
          Précision globale : <strong style={{ color: '#f97316', fontSize: '1.1rem' }}>{acc}%</strong>
          <Typography variant="body2" sx={{ fontSize: '0.65rem', color: '#6b7280', mt: 0.2 }}>
            Sur {total.toLocaleString('fr-FR')} prédictions, {((data.true_positives + data.true_negatives)).toLocaleString('fr-FR')} sont correctes
          </Typography>
        </Typography>
      </Box>
    </Box>
  );
}
