import { Box, Typography } from '@mui/material';
import { BarChart } from '@mui/x-charts/BarChart';
import { TrendingUp } from 'lucide-react';

export default function FeatureImportanceChart({ data }) {
  const sorted = [...data].sort((a, b) => b.importance - a.importance);

  return (
    <Box sx={{ bgcolor: 'background.paper', borderRadius: 3, border: '1px solid', borderColor: 'divider', p: { xs: 2, md: 2.5 }, height: '100%' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
        <TrendingUp size={18} color="#f97316" />
        <Typography variant="h6">Importance des Caractéristiques</Typography>
      </Box>
      <Typography variant="body2" sx={{ mb: 1.5, fontSize: '0.72rem' }}>
        Poids de chaque variable dans les décisions du modèle Random Forest
      </Typography>
      <BarChart
        dataset={sorted}
        yAxis={[{ scaleType: 'band', dataKey: 'feature', tickLabelStyle: { fontSize: 11, fontWeight: 500 } }]}
        xAxis={[{ tickFormatter: (v) => `${(v * 100).toFixed(0)}%`, min: 0, max: 1 }]}
        series={[{ dataKey: 'importance', label: 'Importance', color: '#f97316' }]}
        layout="horizontal"
        height={260}
        slotProps={{ legend: { hidden: true } }}
        borderRadius={6}
      />
    </Box>
  );
}
